            for (int i = 0; i < blockSide; i++) {
                for (int j = 0; j < blockSide; j++) {
                    for (int k = 0; k < blockSide; k++) {
                        // Loop over points in the current block
                        for (int l = 0; l < n_points[i][j][k]; l++) {
                            // Loop over the 3x3x3 neighborhood
                            for (int di = -1; di <= 1; di++) {
                                for (int dj = -1; dj <= 1; dj++) {
                                    for (int dk = -1; dk <= 1; dk++) {
                                        int ni = i + di;
                                        int nj = j + dj;
                                        int nk = k + dk;
                                        // Check if neighbor block is valid
                                        if (ni >= 0 && ni < blockSide && 
                                            nj >= 0 && nj < blockSide && 
                                            nk >= 0 && nk < blockSide) {
                                            // Loop over points in the neighbor block
                                            for (int m = 0; m < n_points[ni][nj][nk]; m++) {
                                                // Skip self-interaction
                                                if (i == ni && j == nj && k == nk && l == m) {
                                                    continue;
                                                }
                                                // Compute distance vector
                                                TYPE dx = position[i][j][k][l].x - position[ni][nj][nk][m].x;
                                                TYPE dy = position[i][j][k][l].y - position[ni][nj][nk][m].y;
                                                TYPE dz = position[i][j][k][l].z - position[ni][nj][nk][m].z;
                                                TYPE r2 = dx*dx + dy*dy + dz*dz;
                                                // Avoid division by zero and very close particles
                                                if (r2 < 1e-10) {
                                                    continue;
