        #include "md_grid.h"

        void md(
            int32_t n_points[blockSide][blockSide][blockSide],
            dvector_t force[blockSide][blockSide][blockSide][densityFactor],
            dvector_t position[blockSide][blockSide][blockSide][densityFactor]
        ) {
            // Loop over blocks: i, j, k (loop_grid0)
            for (int i = 0; i < blockSide; i++) {
                for (int j = 0; j < blockSide; j++) {
                    for (int k = 0; k < blockSide; k++) {

                        // Loop over points in current block (loop_p)
                        for (int p = 0; p < n_points[i][j][k]; p++) {

                            // Loop over 3x3x3 neighbor blocks (loop_grid1)
                            for (int di = -1; di <= 1; di++) {
                                for (int dj = -1; dj <= 1; dj++) {
                                    for (int dk = -1; dk <= 1; dk++) {

                                        int ni = i + di;
                                        int nj = j + dj;
                                        int nk = k + dk;

                                        // Check if neighbor block is within grid
                                        if (ni < 0 || ni >= blockSide ||
                                            nj < 0 || nj >= blockSide ||
                                            nk < 0 || nk >= blockSide) {
                                            continue;
                                        }

                                        // Loop over points in neighbor block (loop_q)
                                        for (int q = 0; q < n_points[ni][nj][nk]; q++) {

                                            // Skip self-interaction: same block and same point
                                            if (ni == i && nj == j && nk == k && q == p) {
                                                continue;
                                            }

                                            // Compute distance vector
                                            TYPE dx = position[ni][nj][nk][q].x - position[i][j][k][p].x;
                                            TYPE dy = position[ni][nj][nk][q].y - position[i][j][k][p].y;
                                            TYPE dz = position[ni][nj][nk][q].z - position[i][j][k][p].z;

                                            // Compute squared distance
                                            TYPE r2 = dx*dx + dy*dy + dz*dz;

                                            // Avoid division by zero and very small distances
                                            if (r2 < 1e-10) {
                                                continue;
                                            }

                                            // Compute inverse squared distance
                                            TYPE r2inv = 1.0 / r2;
                                            TYPE r6inv = r2inv * r2inv * r2inv;
                                            TYPE r12inv = r6inv * r6inv;

                                            // Compute the force magnitude factor
                                            TYPE f = (12.0 * lj1 * r12inv - 6.0 * lj2 * r6inv) * r2inv;

                                            // Update the force on point p
                                            force[i][j][k][p].x += dx * f;
                                            force[i][j][k][p].y += dy * f;
                                            force[i][j][k][p].z += dz * f;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
